suppressPackageStartupMessages({library(data.table);library(Seurat);library(jsonlite)})
root<-normalizePath(commandArgs(TRUE)[1]);source(file.path(root,'code/load_result.R'))
for(s in c('Cervilla','D1_Johnson')){x<-load_bin8(file.path(root,s));ids<-x@misc$analysis_bin_ids;d<-fread(file.path(root,s,'rctd_ROI_results.tsv.gz'));keep<-d$bin_id[d$qc_keep];stopifnot(sum(x$rctd_status!='not_tested')==length(keep),all(!is.na(x$rctd_status)),all(c('singler_blca_marker_count','singler_hpca_marker_count')%in%names(x[[]])),dir.exists(x@misc$resolved_spatial_assets));v<-read_json(file.path(root,s,'validation.json'),simplifyVector=TRUE);v$loader_RCTD_alignment<-TRUE;v$loader_assets_resolve<-TRUE;write_json(v,file.path(root,s,'validation.json'),auto_unbox=TRUE,pretty=TRUE);cat('LOADER_OK',s,ncol(x[['RNA']]),'\n');rm(x);gc()}
